func line(a: Vector3, b: Vector3) -> void:
	if a.is_equal_approx(b):
		push_error("line(): the two points are one point: no line")

func triangle(a: Vector3, b: Vector3, c: Vector3) -> void:
	if (b - a).cross(c - a).length() < 0.000001:
		push_error("triangle(): the three points are in one line: no face")

func mouse_point() -> Vector3:
	var t := Engine.get_process_frames() * 0.1
	return Vector3(cos(t), 0, sin(t)) * 2.0

func cell_at(x: int, z: int) -> Node3D:
	var found: Node3D = null
	for c in get_parent().get_children():
		if c is Node3D and is_equal_approx(c.position.x, x) and is_equal_approx(c.position.z, z):
			found = c
	return found

func band(i: int, n: int, colour: Color) -> void:
	if i < 0 or i >= n:
		push_error("band(): band %d of %d is not on the arch" % [i, n])
